$_LANG['cloudSlider']['feature01Description'] = "Server-uptime is cruciaal voor ieder bedrijf — beschouw het als de hartslag van uw onderneming zonder welke u niet bestaat. Bestands- en databaseservers, e-mail- en webservers zijn een onmisbaar onderdeel voor veel bedrijfsprocessen en uitval heeft direct gevolgen voor uw productiviteit, verkoop en de tevredenheid van zowel medewerkers als klanten. Daarom is het zo belangrijk voor ons om de maximale uptime van uw server te garanderen. Wij willen ervoor zorgen dat uw bedrijfsprocessen gezond verlopen en u uw klanten tevreden kunt houden.";
$_LANG['cloudSlider']['feature01DescriptionTwo'] = "Wanneer u op ons vertrouwt voor uw zakelijke behoeften, beloven wij een uptime van 99,9% voor alle door ons geleverde diensten (buiten het standaardonderhoud).";
$_LANG['cloudSlider']['feature01Title'] = "Maximale server-uptime";
$_LANG['cloudSlider']['feature02Description'] = "Onze diensten worden mogelijk gemaakt met behulp van honderden servers en datacenters over de hele wereld. Zo kunt u erop vertrouwen dat klanten overal toegang hebben tot uw website. Daarnaast bieden we monitoringtools om u deskundige analyses te bieden: inzicht in uw websiteverkeer is belangrijk om de efficiëntie en populariteit van uw site te verbeteren en om bij te houden waar uw bezoekers vandaan komen, op welk tijdstip ze u bezoeken en hoe lang ze blijven. Onze toewijding aan wereldwijde dienstverlening blijkt ook uit onze domeinregistratie, waarbij wij alle populaire TLD's aanbieden.";
$_LANG['cloudSlider']['feature02DescriptionTwo'] = "Onze klanten zijn belangrijk voor ons, waar ter wereld zij zich ook bevinden. We staan klaar voor alle hosting-ondersteuning die u nodig hebt, via telefoon, e-mail of live chat.";
$_LANG['cloudSlider']['feature02Title'] = "Wereldwijd data toevoer";
$_LANG['cloudSlider']['feature03Description'] = "Wees gerust, wij bieden 24 uur per dag, 7 dagen per week veiligheidsmonitoring en bescherming tegen DDoS-aanvallen. U neemt de beschering van de data van uw klanten serieus, wij doen dan ook. Ons beveiligingsteam en onze beveiligingssystemen werken de hele dag door om het beveiligingsniveau te leveren dat in dit digitale tijdperk noodzakelijk is.";
$_LANG['cloudSlider']['feature03DescriptionTwo'] = "Wij bieden een breed scala aan beveiligingssystemen, waaronder SSL-certificaten, firewall-configuraties, beveiligingsmonitoring, toegang via VPN, en nog veel meer.";
$_LANG['cloudSlider']['feature03Title'] = "Beveiliging van topniveau";
$_LANG['cloudSlider']['selectProductLevel'] = "Selecteer het niveau dat bij u past";
