$_LANG['store']['addon']['wptk']['faqA1'] = "WP Toolkit is een interface voor WordPress van cPanel en Plesk; hiermee kunt u WordPress-websites installeren, configureren en beheren.";
$_LANG['store']['addon']['wptk']['faqA2'] = "WP Toolkit Deluxe is een betaalde upgrade met geavanceerde functies voor beheer van plugins en thema's, staging, klonen, Smart Updates, en meer.";
$_LANG['store']['addon']['wptk']['faqA3'] = "Smart Updates test updates voor thema's, plugins, talen en voor WordPress zelf, automatisch, in een volledig veilige omgeving, zodat de live website geen risico loopt.";
$_LANG['store']['addon']['wptk']['faqA4'] = "WP Toolkit Deluxe is beschikbaar als add-on voor bepaalde hostingpakketten. <a href=\":webRoot/login.php\">Meld u aan</a> om de prijzen voor uw bestaande domeinen te bekijken, of <a href=\":webRoot/register.php\">registreer</a> als nieuwe klant.";
$_LANG['store']['addon']['wptk']['faqA5'] = "Wie toegang heeft ziet een pictogram van WP Toolkit en een link in het dashboard van cPanel. Wie beschikt over WP Toolkit Deluxe, ziet ook een aanmeldlink in de hostingdienst-weergave in het <a href=\":webRoot/clientarea.php\">klantenportaal</a>.";
$_LANG['store']['addon']['wptk']['faqA6'] = "Smart Updates is beschikbaar als add-on voor relevante hostingpakketten. U kunt u <a href=\":webRoot/login.php\">aanmelden</a> om de prijzen te zien voor uw bestaande domeinen, of u kunt u <a href=\":webRoot/register.php\">registreren</a> als nieuwe klant.";
$_LANG['store']['addon']['wptk']['faqA7'] = "Als u toegang hebt, vindt u het pictogram van WP Toolkit en een link op de hoofdpagina van Plesk. Smart Updates zijn na aankoop beschikbaar.";
$_LANG['store']['addon']['wptk']['faqQ1'] = "Wat is WP Toolkit?";
$_LANG['store']['addon']['wptk']['faqQ2'] = "Wat maakt WP Toolkit Deluxe anders?";
$_LANG['store']['addon']['wptk']['faqQ3'] = "Wat zijn Smart Updates?";
$_LANG['store']['addon']['wptk']['faqQ4'] = "Wat kost WP Toolkit?";
$_LANG['store']['addon']['wptk']['faqQ5'] = "Hoe krijg ik toegang tot WP Toolkit?";
$_LANG['store']['addon']['wptk']['faqQ6'] = "Wat kost Smart Updates?";
$_LANG['store']['addon']['wptk']['faqQ7'] = "Hoe krijg ik toegang tot WP Toolkit?";
$_LANG['store']['addon']['wptk']['featureBody1'] = "Installeer en configureer plugins en thema's om het uiterlijk en de sfeer van een of meer van uw WordPress-websites in slechts een paar klikken aan te passen.";
$_LANG['store']['addon']['wptk']['featureBody2'] = "Kloon een bestaande WordPress-site om designs, plug-ins of welk aspect van de site dan ook te testen. Synchroniseer op elk gewenst moment terug naar de live site.";
$_LANG['store']['addon']['wptk']['featureBody3'] = "Met één klik op de knop worden uw WordPress-websites gescand en beschermd tegen geselecteerde beveiligingsrisico's. Het is ook mogelijk om specifieke sites of pagina's met een wachtwoord af te schermen.";
$_LANG['store']['addon']['wptk']['featureBody4'] = "Smart Updates identificeert en analyseert updates automatisch op compatibiliteit en veiligheid. Vervolgens worden ze ofwel geïnstalleerd, of u ontvangt een melding bij problemen, opdat de veiligheid van uw site gegarandeerd blijft.";
$_LANG['store']['addon']['wptk']['featureBody5'] = "Maak een kopie van een live site om mee te experimenteren, terwijl al uw WordPress-sites met één klik beschermd blijven.";
$_LANG['store']['addon']['wptk']['featureBody6'] = "Zet websites offline waarbij er een aangepast bericht wordt getoond.";
$_LANG['store']['addon']['wptk']['featureTitle1'] = "Snel en gemakkelijk bouwen";
$_LANG['store']['addon']['wptk']['featureTitle2'] = "Veilig experimenteren";
$_LANG['store']['addon']['wptk']['featureTitle3'] = "Gerust gevoel";
$_LANG['store']['addon']['wptk']['featureTitle4'] = "Updates automatiseren";
$_LANG['store']['addon']['wptk']['featureTitle5'] = "Klonen en beveiligingsversterking";
$_LANG['store']['addon']['wptk']['featureTitle6'] = "Onderhoudsmodus";
$_LANG['store']['addon']['wptk']['for'] = "voor";
$_LANG['store']['addon']['wptk']['getItNow'] = "Aan de slag";
$_LANG['store']['addon']['wptk']['getStartedToday'] = "Ga vandaag nog aan de slag met WP Toolkit Deluxe!";
$_LANG['store']['addon']['wptk']['introBody'] = "Geen giswerk en gedoe meer bij het beheer van WordPress! Alle normale functies zijn aanwezig, van het eenvoudig aanmaken en terugplaatsen van reservekopieën tot het beheren van de index voor zoekmachines en aanmelden met één klik bij WordPress. Maar ook horen hier automatische Smart Updates bij, staging en klonen om eenvoudig bestaande websites te dupliceren of te testen, het versterken van de beveiliging met één klik, en nog veel meer.";
$_LANG['store']['addon']['wptk']['introTitle'] = "WP Toolkit Deluxe betekent krachtig beheer van WordPress® plugins en thema's, beveiliging, automatisering, klonen en reservekopieën, allemaal vanuit één gebruiksvriendelijk dashboard.";
$_LANG['store']['addon']['wptk']['loginNow'] = "Nu aanmelden";
$_LANG['store']['addon']['wptk']['loginToSeePricing'] = "Meld u aan om de tarieven te zien voor het toevoegen aan uw bestaande webhosting";
$_LANG['store']['addon']['wptk']['midTitle1'] = "De enige toolkit die u :breaktag ooit nodig zult hebben...";
$_LANG['store']['addon']['wptk']['midTitle2'] = "De meest complete, veilige en veelzijdige toolkit voor WordPress";
$_LANG['store']['addon']['wptk']['plesk']['featureBody1'] = "Installatieprogramma om WordPress met één klik van start to finish te initialiseren en in te stellen. Eén dashboard voor het beheren van meerdere WordPress tegelijk.";
$_LANG['store']['addon']['wptk']['plesk']['featureBody2'] = "Test nieuwe functies en ideeën voor ze live gaan in een veilige testomgeving — zonder plugins of aparte servers.";
$_LANG['store']['addon']['wptk']['plesk']['featureBody3'] = "Standaardverbetering van de beveiliging van uw site, verder aangevuld met de WP Toolkit beveiligingsscanner. Geen specifieke beveiligingsexpertise vereist.";
$_LANG['store']['addon']['wptk']['plesk']['featureBody4'] = "Pas updates voor WordPress en de gebruikte thema's en plugins afzonderlijk toe, of in bulk. Bewaak en beheer al uw WordPress-sites vanuit één dashboard.";
$_LANG['store']['addon']['wptk']['plesk']['featureBody5'] = "Stagen, klonen, synchroniseren, updaten, migreren en andere complexe taken worden met één klik uitgevoerd. Geen gestresste ontwikkelaars en risicovolle bewerkingen meer.";
$_LANG['store']['addon']['wptk']['plesk']['featureBody6'] = "Volledige controle met WP-CLI, onderhoudsmodus, debugbeheer, indexbeheer voor zoekmachines, en meer.";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle1'] = "WordPress vereenvoudigd";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle2'] = "Staging en testen";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle3'] = "Goed beveiligd tegen aanvallen";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle4'] = "Uitvoeren en Automatiseren";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle5'] = "Weg met complexiteit";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle6'] = "Eenvoudig, maar niet amateuristisch";
$_LANG['store']['addon']['wptk']['pleskIntroBody'] = "Met behulp van geavanceerde intelligentie en automatisering houdt Smart Updates WordPress websites altijd up-to-date, online en beschermd tegen mogelijk schadelijke updates van uw kernbestanden, plugins en thema's.";
$_LANG['store']['addon']['wptk']['pleskIntroTitle'] = "Smart Updates for WP Toolkit identificeert en analyseert mogelijke updates voor WordPress-installaties en voert vervolgens de update uit zonder risico voor uw live website, of geeft een melding dat er een potentieel gevaarlijke update beschikbaar is.";
$_LANG['store']['addon']['wptk']['pleskTagline'] = "Geef WordPress een flinke boost";
