$_LANG['store']['addon']['wptk']['redefined2'] = "WP Toolkit Deluxe voor";
$_LANG['store']['addon']['wptk']['screenshotDesc'] = "WP Toolkit Deluxe biedt alles om WordPress-websites te installeren, configureren, updaten en beveiligen. Upgrade vandaag nog naar WP Toolkit Deluxe voor slechts :price.";
$_LANG['store']['addon']['wptk']['screenshotDescFree'] = "WP Toolkit Deluxe biedt alles om WordPress-websites te installeren, configureren, updaten en beveiligen. Upgrade vandaag nog naar WP Toolkit Deluxe.";
