$_LANG['store']['codeGuard']['faq']['a1'] = "CodeGuard is een volledig geautomatiseerde dienst voor reservekopieën die volledige bescherming biedt tegen gegevensverlies en malware.";
$_LANG['store']['codeGuard']['faq']['a2'] = "CodeGuard biedt een oplossing waarbij reservekopieën van uw website extern worden opgeslagen in een onafhankelijke opslag, gecombineerd met dagelijkse monitoring om ervoor te zorgen dat uw website online blijft en vrij is van malware.";
$_LANG['store']['codeGuard']['faq']['a3'] = "CodeGuard maakt elke dag geautomatiseerde snapshots van uw website. Met behulp van deze snapshots kunt u op elk moment een eerdere versie van uw volledige website of van een specifiek bestand terugplaatsen.";
