$_LANG['store']['codeGuard']['faq']['a7'] = "Ja, ook van databases kan een reservekopie worden gemaakt. Database-reservekopieën worden ondersteund voor MySQL- en MSSQL-databases.";
$_LANG['store']['codeGuard']['faq']['a8'] = "CodeGuard kan websites monitoren en een melding per e-mail versturen wanneer er een verandering wordt gedetecteerd, om zo mogelijke nieuwe bedreigingen en malware snel op te merken.";
$_LANG['store']['codeGuard']['faq']['a9'] = "Met de dagelijkse reservekopieën van CodeGuard kunnen websites die worden aangevallen op elk moment worden hersteld naar een eerdere niet-geïnfecteerde versie.";
