$_LANG['store']['codeGuard']['features']['wp'] = "Automatische WordPress-updates";
$_LANG['store']['codeGuard']['features']['wpDescription'] = "Werk WordPress en de bijbehorende plugins automatisch bij om alles veilig te houden, met automatisch herstel bij problemen.";
