$_LANG['store']['codeGuard']['leadText1'] = "Bescherm uw website tegen <strong>gegevensverlies en corruptie</strong> en tegen de bedreiging van <strong>virussen, hackers en malware</strong> met de dagelijkse geautomatiseerde website-reservekopieën van CodeGuard.";
