$_LANG['store']['emailServices']['archiving']['title'] = "E-mailarchivering";
$_LANG['store']['emailServices']['benefits']['archiving']['1'] = "Inclusief filtering van inkomende en uitgaande e-mail!";
$_LANG['store']['emailServices']['benefits']['archiving']['2'] = "Raak nooit meer een e-mail kwijt!";
$_LANG['store']['emailServices']['benefits']['archiving']['3'] = "Zorg voor compliance";
$_LANG['store']['emailServices']['benefits']['archiving']['4'] = "Verbeter de prestaties van uw IT-systeem";
$_LANG['store']['emailServices']['benefits']['archiving']['5'] = "Gebruiksvriendelijk beheer van gegevensbescherming";
$_LANG['store']['emailServices']['benefits']['archiving']['6'] = "E-mailcontinuïteit, logboekregistratie en eenvoudig opnieuw verzending toegevoegd.";
$_LANG['store']['emailServices']['benefits']['archiving']['7'] = "Gecomprimeerd, versleuteld en veilig archief";
$_LANG['store']['emailServices']['benefits']['archiving']['a1'] = "E-mailarchivering betekent het bewaren en beschermen van alle inkomende en uitgaande e-mailberichten, zodat deze later kunnen worden teruggevonden. Het is een geweldige manier om verloren of per ongeluk verwijderde e-mails te herstellen, om sneller op audits te reageren, e-mails en bijlagen over intellectueel eigendom te beveiligen en voor „eDiscovery” bij geschillen of rechtzaken.";
$_LANG['store']['emailServices']['benefits']['archiving']['a2a'] = "Wanhopig op zoek naar die ene e-mail van vorig jaar, omdat er anders een boete volgt of een zakelijke deal in het gevaar komt? Voorkom dit met professionele e-mailarchivering! E-mailarchivering is een cruciaal hulpmiddel om een veilige reservekopie van alle e-mail te bewaren en te voldoen aan wettelijke vereisten.";
$_LANG['store']['emailServices']['benefits']['archiving']['a2b'] = "Tegelijkertijd, omdat e-mailberichten rechtskracht hebben en wettelijk bindend zijn, is e-mailcompliance voor organisaties zeer belangrijk geworden. Daarom is het in bepaalde sectoren wettelijk verplicht om een veilige reservekopie van alle e-mailberichten te bewaren.";
$_LANG['store']['emailServices']['benefits']['archiving']['q1'] = "E-mailarchivering";
$_LANG['store']['emailServices']['benefits']['archiving']['q2'] = "Waarom dit zo nuttig is";
$_LANG['store']['emailServices']['benefits']['archiving']['title'] = "Het archiveren van e-mail heeft al deze voordelen...";
$_LANG['store']['emailServices']['benefits']['incoming']['1'] = "Volledige postvak-bescherming tegen een concurrerende prijs";
$_LANG['store']['emailServices']['benefits']['incoming']['2'] = "Uiterst nauwkeurige filtering";
$_LANG['store']['emailServices']['benefits']['incoming']['3'] = "Eenvoudige configuratie";
$_LANG['store']['emailServices']['benefits']['incoming']['4'] = "Verhoogt de continuïteit en redundantie van inkomende e-mail";
$_LANG['store']['emailServices']['benefits']['incoming']['5'] = "Verschillende rapportagemogelijkheden";
$_LANG['store']['emailServices']['benefits']['incoming']['6'] = "Gebruiksvriendelijke interface voor volledige controle over uw e-mail";
$_LANG['store']['emailServices']['benefits']['incoming']['7'] = "Verhoogt de productiviteit van medewerkers";
$_LANG['store']['emailServices']['benefits']['incoming']['8'] = "Compatibel met elke mailserver";
$_LANG['store']['emailServices']['benefits']['incoming']['a1'] = "Het filter voor inkomende e-mail filtert alle inkomende e-mail en maakt spam en virussen - met een nauwkeurigheid van bijna 100% - onschadelijk vóór ze uw netwerk bereiken. Het uitgebreide controlepaneel zorgt ervoor dat u de volledige controle behoudt. Bovendien wordt uw e-mail in de wachtrij geplaatst als uw e-mailserver even niet beschikbaar is. E-mails in de wachtrij kunnen via de webinterface worden geopend, gelezen en beantwoord, zodat de continuïteit van uw inkomende e-mail gewaarborgd is.";
$_LANG['store']['emailServices']['benefits']['incoming']['a2'] = "Zorg dat uw IT-netwerk geen onnodig risico loopt. Als uw postvak elke dag vol zit met ongevraagde bulkmail, dan toont dit de noodzaak van een professioneel inkomend filter aan. Met volledige bescherming van uw Postvak In is het afgelopen met de dreiging van spam, virussen en malware!";
$_LANG['store']['emailServices']['benefits']['incoming']['a3'] = "Zodra uw domein (automatisch) is toegevoegd aan het inkomende filter en de filtering is ingeschakeld, worden alle e-mails eerst door de cloud van SpamExperts gestuurd voor controle. Inkomende e-mails worden veilig en in realtime geanalyseerd en gescand. Er is geen training of configuratie nodig en alles werkt meteen. Elk bericht dat als spam wordt aangemerkt, wordt naar de quarantaine verplaatst; niet-spam wordt direct doorgestuurd naar uw e-mailserver. De quarantaine kan worden bekeken in het gebruiksvriendelijke SpamPanel, via e-mailrapporten of zelfs rechtstreeks in uw e-mailprogramma! Tijdverspilling vanwege spam is verleden tijd, u kunt uw energie weer gewoon richten op uw echte taken, terwijl u toch volledige controle behoudt.";
$_LANG['store']['emailServices']['benefits']['incoming']['q1'] = "Wat maakt de keuze voor het inkomende filter van SpamExperts zo verstandig?";
$_LANG['store']['emailServices']['benefits']['incoming']['q2'] = "Waarom is een professioneel inkomend filter zo belangrijk?";
$_LANG['store']['emailServices']['benefits']['incoming']['q3'] = "Hoe het werkt";
$_LANG['store']['emailServices']['benefits']['incoming']['title'] = "Het filteren van binnenkomende e-mail heeft al deze voordelen...";
$_LANG['store']['emailServices']['benefits']['outgoing']['1'] = "Niet meer op blokkeerlijsten terecht komen";
$_LANG['store']['emailServices']['benefits']['outgoing']['2'] = "De reputatie van uw merk en IT-systemen beschermen";
$_LANG['store']['emailServices']['benefits']['outgoing']['3'] = "De kosten van de-listing vermijden";
$_LANG['store']['emailServices']['benefits']['outgoing']['4'] = "De continuïteit en aflevering van uitgaande e-mail verbeteren";
$_LANG['store']['emailServices']['benefits']['outgoing']['5'] = "De productiviteit van medewerkers verbeteren";
$_LANG['store']['emailServices']['benefits']['outgoing']['6'] = "De beheersbaarheid van misbruik verbeteren";
$_LANG['store']['emailServices']['benefits']['outgoing']['a1'] = "Het filteren van uitgaande e-mail is essentieel om de reputatie van uw IT-infrastructuur te beschermen en ervoor te zorgen dat uw uitgaande e-mail veilig aankomt waar het moet zijn. Deze professionele oplossing voorkomt dat spam en virussen uw netwerk verlaten en at uw IP(s) ooit nog op zwarte lijsten komen te staan. Bovendien biedt het uitgaand filter van SpamExperts u de rapportages en hulpmiddelen om gecompromitteerde accounts te detecteren en spammende gebruikers af te sluiten.";
$_LANG['store']['emailServices']['benefits']['outgoing']['a2'] = "Heeft uw netwerk ooit spam verstuurd zonder dat u dat wist? Kwetsbaarheden in het netwerk kunnen ervoor zorgen dat bijna elk apparaat kan worden gehackt om uitgaande SMTP te verzenden. Hierdoor kan spam of malware vanaf uw netwerk worden verstuurd zonder dat u er erg in heeft. Daarom is het zo belangrijk dat u investeert in een professionele oplossing voor uitgaande spamfilters. Bescherm de reputatie van uw bedrijf, voorkom dat uw netwerk spam verstuurt en dat u op de zwarte lijst terecht komt. Zo zorgt u ervoor dat uw echte e-mail altijd de juiste plek bereikt.";
$_LANG['store']['emailServices']['benefits']['outgoing']['q1'] = "Wat houd het uitgaande filter in?";
$_LANG['store']['emailServices']['benefits']['outgoing']['q2'] = "Waar is het goed voor?";
$_LANG['store']['emailServices']['benefits']['outgoing']['title'] = "Het filteren van uitgaande e-mail heeft al deze voordelen...";
$_LANG['store']['emailServices']['blockSpamHeadline'] = "Houd bijna 100% van de virussen, malware en spam tegen vóór ze de kans krijgen de inbox te bereiken";
$_LANG['store']['emailServices']['domain'] = "domein";
$_LANG['store']['emailServices']['faqs']['a1'] = "E-mail wordt doorgestuurd via de intelligente, zelflerende servers van SpamExperts, die ongewenste mail detecteren en blokkeren voor ze naar de mailserver worden doorgestuurd.";
$_LANG['store']['emailServices']['faqs']['a2'] = "Omdat ze miljoenen e-mails per dag verwerken, zijn onze e-mailfilters toonaangevend met een nauwkeurigheidsscore van bijna 100%.";
$_LANG['store']['emailServices']['faqs']['a3'] = "Ja, met een uitgebreid controlepaneel met een zoekfunctie voor de logbestanden, quarantaine en vele andere hulpmiddelen is het mogelijk de status te controleren van elke e-mail die door het systeem is gegaan.";
