$_LANG['store']['nordvpn']['features']['security']['tagline1'] = "Als je bescherming tegen hackers en online monitoring nodig hebt, dan kunt u uw verbinding beveiligen met een virtual private network (VPN) van NordVPN.";
$_LANG['store']['nordvpn']['features']['security']['tagline2'] = "Gebruik NordVPN om uw online activiteiten te versleutelen voor een extra beschermingslaag, waar en wanneer u bent verbonden.";
$_LANG['store']['nordvpn']['features']['security']['tagline3'] = "NordVPN beveiligt je verbinding met versleuteling van de volgende generatie, zodat je zonder zorgen kunt inloggen op je accounts, bankoverschrijvingen kunt doen en online kunt winkelen. Zelfs op onbeveiligde netwerken.";
$_LANG['store']['nordvpn']['features']['security']['tagline4'] = "Het gaat niemand iets aan wat u online doet. Daarom volgen wij u niet en verzamelen en delen wij geen privégegevens. Wij kunnen zelfs geen details over u aan derden verstrekken, ook niet als ze erom vragen.";
$_LANG['store']['nordvpn']['features']['security']['tagline5'] = "NordVPN beschikt over een breed scala aan functies om je te beschermen tegen cyberbedreigingen. Naast Threat Protection Pro™ is er een automatische Kill Switch die je internetverbinding blokkeert als je VPN-verbinding wegvalt, zodat je gegevens veilig blijven. Verduisterde servers helpen wanneer een hoog niveau van online beveiliging vereist is vanwege overheidscensuur en strikte internetvoorschriften.";
$_LANG['store']['nordvpn']['features']['security']['title1'] = "Verbeter uw online veiligheid met een VPN";
