$_LANG['store']['nordvpn']['features']['threat']['safe'] = "Threat Protection Pro™ beschermt je apparaten en je privacy. Door trackers te blokkeren, kunt u online snoopers vermijden.";
$_LANG['store']['nordvpn']['features']['threat']['tagline'] = "De :tagOpenThreat Protection Pro ™:tagClose-functie van NordVPN is een gamechanger die nog meer veiligheidsvoordelen en betere bescherming biedt met maar één extra klik.";
$_LANG['store']['nordvpn']['features']['threat']['title'] = "Meer dan een VPN";
$_LANG['store']['nordvpn']['features']['use']['tagline1'] = "Ook wie niets heeft te verbergen, zit er waarschijnlijk niet op te wachten om te worden begluurd en gevolgd. De belangrijkste reden waarom internetgebruikers voor een VPN kiezen, is online privacy en veiligheid in het algemeen.:tagBreakMaar WAAROM precies?";
$_LANG['store']['nordvpn']['features']['use']['tagline2'] = "Openbare wifi-netwerken in hotels, luchthavens en coffeeshops zijn de perfecte doelwitten voor hackers vanwege de vaak lage beveiligingsmaatregelen.";
