$_LANG['store']['ox']['appSuite'] = "OX-app-suite";
$_LANG['store']['ox']['cartShortDescription'] = "Kies voor professionele zakelijke e-mail met complete hulpprogramma's voor communicatie en samenwerking, voor veilig en betrouwbaar werken.";
$_LANG['store']['ox']['cartTitle'] = "Professionele e-mail";
$_LANG['store']['ox']['faq1']['answer'] = "Alle OX App Suite-pakketten zijn inclusief toegang tot webmail, agenda, taken en adresboek. Het Productivity-pakket voegt daar nog OX Drive en OX Documents (tekst, spreadsheets en presentaties) aan toe.";
$_LANG['store']['ox']['faq1']['question'] = "Welke apps zijn in OX App Suite inbegrepen?";
$_LANG['store']['ox']['faq2']['answer'] = "Ja, OX App Suite kan verbinding maken met alle externe IMAP-e-mailaccounts, inclusief die van populaire providers zoals Gmail, Yahoo en Outlook.com. Voeg gewoon een e-mailadres en wachtwoord toe aan de App Suite, en elke mail die naar dit account wordt gestuurd verschijnt vanzelf in de App Suite-interface.";
$_LANG['store']['ox']['faq2']['question'] = "Kan ik externe e-mailaccounts koppelen aan OX App Suite?";
$_LANG['store']['ox']['faq3']['answer'] = "Ja, OX App Suite kent volledige ondersteuning voor CalDAV en CardDAV. Voor Android-gebruikers is synchroniseren eenvoudig, via onze speciale Android sync-app.";
$_LANG['store']['ox']['faq3']['question'] = "Kan ik agenda en contacten van OX App Suite en mijn mobiele apparaat synchroniseren?";
$_LANG['store']['ox']['faq4']['answer'] = "App Suite werkt naadloos samen met de meeste standaard e-mailprogramma's voor desktop en mobiel.";
$_LANG['store']['ox']['faq4']['devices'] = "Mobiele apparaten: iPhone op iOS 11/iOS 12, smartphone op Android 4.1 of hoger<br>Ondersteunde browsers: Safari, Chrome (laatste en vorige versie), Mozilla Firefox (laatste en vorige versie), Microsoft Internet Explorer 11/Edge";
$_LANG['store']['ox']['faq4']['question'] = "Werkt OX App Suite op mijn apparaat?";
$_LANG['store']['ox']['faq5']['answer'] = "Jazeker! OX App Suite maakt gebruik van gepatenteerde technologie en werkt samen met gerenommeerde leveranciers in de anti-spamindustrie om uw postvak zo schoon en veilig mogelijk te houden.";
$_LANG['store']['ox']['faq5']['question'] = "Beschermt OX App Suite tegen spam en virussen?";
$_LANG['store']['ox']['faq6']['answer'] = "OX Drive is een online opslag om documenten, foto's en media op te slaan in de cloud. Dit betekent dat toegang tot OX App Suite en OX Drive voldoende is om toegang te krijgen tot alle opgeslagen bestanden. OX Drive synchroniseert met heel veel apparaten via de browser en native apps.";
$_LANG['store']['ox']['faq6']['question'] = "Wat is OX Drive? (Productivity)?";
$_LANG['store']['ox']['faq7']['answer'] = "OX Text, OX Spreadsheet en OX Presentation zijn 3 toepassingen die samen OX Documents vormen. Deze toepassingen kunnen worden gebruikt om tekstdocumenten, spreadsheets en presentaties online aan te maken en te bewerken. Dit kan vanaf elke locatie, op alle apparaten, met de normale functies die u gewend bent van uw Office-toepassingen.";
$_LANG['store']['ox']['faq7']['question'] = "Wat is OX Documents (Productivity)?";
$_LANG['store']['ox']['faq8']['answer'] = "OX App Suite ondersteunt de volgende talen: Engels, Duits, Spaans, Frans, Italiaans, Nederlands, Pools, Engels, Engels, Engels, Pools, 中文 简体, 中文 繁體 en 日本語";
$_LANG['store']['ox']['faq8']['question'] = "Welke talen worden door OX App Suite ondersteund?";
$_LANG['store']['ox']['faq9']['answer'] = "Ja, we bieden een hulpprogramma om om zelf een migratie uit te voeren; deze is intuïtief en gebruiksvriendelijk. Migreer vanaf alle populaire e-maildiensten, waaronder Apple iCloud, Gmail, Outlook.com/Windows Live/Hotmail, Yahoo Mail, GMX of T-Online, of voer handmatig de IMAP- of POP3-gegevens van de provider in, of gebruik een van de andere beschikbare protocollen.";
$_LANG['store']['ox']['faq9']['question'] = "Kan ik mijn bestaande e-mailaccount van een andere provider migreren?";
$_LANG['store']['ox']['feature1']['detail'] = "Sla uw belangrijke documenten veilig op in de cloud en deel ze met anderen. Met (tot) 50 GB opslag is er voor jaren voldoende ruimte.";
$_LANG['store']['ox']['feature1']['title'] = "Opslag van bestanden in de cloud";
