$_LANG['store']['ox']['feature2']['title'] = "Agenda's en contactpersonen";
$_LANG['store']['ox']['feature3']['detail'] = "Hier vindt u al uw favoriete e-mailfuncties, zoals doorstuuradressen, aliassen, automatische beantwoording, filters, handtekeningen, meldingen en meer!";
$_LANG['store']['ox']['feature3']['title'] = "Heel veel e-mailfuncties";
