$_LANG['store']['siteBuilder']['featuresTitle'] = "Functies van Site Builder";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['1'] = "Deel verhalen en kom zo in contact met bezoekers via een eigen blog op de website. Stel in hoe berichten op de gepubliceerde website moeten worden weergegeven.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['2'] = "Maak nu blogposts en sla deze op voor latere publicatie, zodat ze precies op het juiste moment komen voor een specifieke gebeurtenis of aanbieding.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['3'] = "Wijzig blogposts nadat ze al zijn gepubliceerd met behulp van de ingebouwde editor voor het schrijven van content.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['4'] = "Moedig bezoekers aan om content te liken en delen door pictogrammen voor sociale media als Facebook, X, LinkedIn en Pinterest aan de site toe te voegen.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['5'] = "Geef bezoekers de mogelijkheid om te reageren en de koppelde Facebook-pagina te liken zonder de website te verlaten.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['6'] = "Toon Instagram-foto's automatisch op de website zodra een post wordt geplaatst en houd sitebezoekers op de hoogte met een live feed vanaf X.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['1'] = "Met de drag-and-drop-editor kunnen klanten website-functies direct toevoegen aan en rangschikken op de pagina, met hulp van markeringen die de beste plaatsen op de pagina aangeven.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['2'] = "Gebruik kant-en-klare vormgevingselementen zoals tekst, knoppen, foto's en pictogrammen om tot een professioneel uitziende indeling van de website te komen.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['3'] = "Verspil geen tijd aan het voortdurend aanpassen van de layout. Met een verzameling van meer dan 350 contentblokken kan zonder technische vaardigheden een professionele website worden gebouwd.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['4'] = "Websites zien er op elk apparaat geweldig uit. Sjablonen passen zich volledig aan het apparaat aan, ook op smartphones, tablets en desktops.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['5'] = "Maak websites beter met een selectie van meer dan 200.000 professionele premiumfoto's in hoge resolutie. Onze Site Builder beschikt zelfs over functies voor het integreren van video's en het optimaliseren van afbeeldingen.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['6'] = "Raak nooit meer werk kwijt dankzij het in realtime opslaan van wijzigingen. De editor slaat al uw werk automatisch op.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['1'] = "Voor een boetiek, winkel of grote zaak zijn er pakketten beschikbaar voor 10, 50 of 500 producten.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['10'] = "Ontvang bij een bestelling direct een melding via e-mail. Beheer en bekijk het overzicht van alle bestellingen, zoek naar specifieke bestellingen, filter bestelling op categorie, werk bestellingen en klantgegevens bij en voeg na verzending trackingnummers toe.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['2'] = "Maak een koppeling met Paypal, Square, Stripe en meer dan 50 vertrouwde aanbieders van creditcardbetalingen om direct creditcards te accepteren.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['3'] = "Laat klanten snel en eenvoudig afrekenen met optionele registratie op de bestelpagina. Zorg voor een veilige bestelprocedure van één pagina, waar klanten ook opmerkingen over de bestelling kunnen achterlaten.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['5'] = "Kies uit meerdere indelingen voor productpagina's en pas de beschrijving en het ontwerp naar eigen inzicht aan. Maak het makkelijker voor klanten om producten te vinden door ze in te delen in categorieën.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['6'] = "Maak coupons of promotiecodes aan om de verkoop te stimuleren. Verhoog de conversie door reguliere prijzen en kortingen naast elkaar weer te geven.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['7'] = "Met voorraadbeheer is het altijd duidelijk wanneer een productvoorraad moet worden aangevuld en welke varianten van een product het populairst zijn.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['8'] = "Reken klanten de verzendkosten in realtime voor door de bestelpagina van uw webwinkel te koppelen aan een of meer verzendbedrijven.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['9'] = "Bereken de belastingen voor verschillende landen afzonderlijk of definieer specifieke zones. Volledige controle over de berekening: stel belasting in per locatie, voeg belasting toe per groep van producten en stel belastingvrije producten in.";
$_LANG['store']['siteBuilder']['intro1'] = "Om op internet aanwezig te zijn is een keuze voor het juiste platform noodzakelijk. Onze drag-and-drop doe-het-zelf Site Builder helpt om op te vallen.";
$_LANG['store']['siteBuilder']['intro2'] = "Voor persoonlijke promotie of voor het onder de aandacht te brengen van een bedrijf, biedt onze websitebouwer een sjabloon en een wizard om content aan te maken. Het systeem is eenvoudig genoeg voor beginners en biedt een rijke functionaliteit, zodat ook professionals ermee uit de voeten kunnen. Het voelt een beetje aan als PowerPoint, maar dan krachter, eleganter en eenvoudiger. Het is een oplossing die veel mensen met plezier gebruiken.";
