$_LANG['store']['sitelock']['buyNow'] = "Nu aanschaffen";
$_LANG['store']['sitelock']['cartShortDescription'] = "SiteLock biedt functies die zijn ontworpen om zowel uw website als de reputatie van uw bedrijf te beschermen.";
$_LANG['store']['sitelock']['cartTitle'] = "SiteLock Website beveiliging";
$_LANG['store']['sitelock']['comparePlans'] = "SiteLock-pakketten vergelijken";
$_LANG['store']['sitelock']['comparePlansSubtitle'] = "Professionele beveiligingsfuncties voor uw website";
$_LANG['store']['sitelock']['contentBodyParagraph1'] = "SiteLock&trade;, de wereldleider op het gebied van websitebeveiliging, beschermt uw website zodat u weer een zorg minder heeft.";
$_LANG['store']['sitelock']['contentBodyParagraph2'] = "De dagelijkse malware-scan van SiteLock identificeert kwetsbaarheden en kwaadaardige code om deze automatisch van uw website te verwijderen. Zo beschermt u uw website en bezoekers tegen bedreigingen.";
$_LANG['store']['sitelock']['contentBodyParagraph3'] = "Bovendien krijgt u het SiteLock Trust Seal, waarmee het klantenvertrouwen wordt verhoogt, iets waarvan is bewezen dat het verkoop- en conversieratio's kan verbeteren.";
$_LANG['store']['sitelock']['contentHeadline'] = "Websitebeveiliging en bescherming tegen malware voor uw website";
$_LANG['store']['sitelock']['emergencyPlanAftercareContent'] = "We blijven uw site 7 dagen lang controleren om ervoor te zorgen dat de site na reparatie vrij van malware blijft.";
$_LANG['store']['sitelock']['emergencyPlanAftercareTitle'] = "7 dagen nazorg";
$_LANG['store']['sitelock']['emergencyPlanBody'] = "Als een website is aangevallen of gehackt, vraag dan onmiddellijk assistentie om de site snel te herstellen. Dit is hoe SiteLock Emergency Response helpt:";
$_LANG['store']['sitelock']['emergencyPlanHeadline'] = "Los het direct op met SiteLock Emergency Response";
$_LANG['store']['sitelock']['emergencyPlanMalwareContent'] = "Als onze automatische technologie de schadelijke inhoud niet kan verwijderen, voeren we een handmatige reparatie uit.";
$_LANG['store']['sitelock']['emergencyPlanMalwareTitle'] = "Volledige verwijdering van malware";
$_LANG['store']['sitelock']['emergencyPlanOnlyCost'] = "Slechts :price voor 7 dagen bescherming";
$_LANG['store']['sitelock']['emergencyPlanPaymentContent'] = "De noodhulpdienst is beschikbaar voor een eenmalige vergoeding; er zijn geen terugkerende kosten of abonnementskosten.";
$_LANG['store']['sitelock']['emergencyPlanPaymentTitle'] = "Eenmalige betaling";
$_LANG['store']['sitelock']['emergencyPlanPriorityContent'] = "Met het noodpakket krijgt u voorrang en komt u meteen bovenaan de wachtrij te staan.";
$_LANG['store']['sitelock']['emergencyPlanPriorityTitle'] = "Voorrang";
$_LANG['store']['sitelock']['emergencyPlanResponseContent'] = "Profiteer van onze snelste reactietijd inclusief analyse en werk om uw website binnen 30 minuten weer aan de praat te krijgen.";
$_LANG['store']['sitelock']['emergencyPlanResponseTitle'] = "Onmiddellijke reactie";
$_LANG['store']['sitelock']['emergencyPlanTitle'] = "Gehackte website?";
$_LANG['store']['sitelock']['emergencyPlanUpdatesContent'] = "Volg de voortgang met realtime updates tijdens het proces van het opschonen en herstellen van de site.";
$_LANG['store']['sitelock']['emergencyPlanUpdatesTitle'] = "Realtime updates";
$_LANG['store']['sitelock']['faq'] = "FAQ";
$_LANG['store']['sitelock']['faqFiveBody'] = "Nee. Tijdens een websitescan downloadt SiteLock de relevante bestanden naar een beveiligde server waar de scans worden uitgevoerd. Dit heeft geen enkele invloed op de content van de website, code, bandbreedte of server-resources.";
$_LANG['store']['sitelock']['faqFiveTitle'] = "Heeft SiteLock invloed op de prestaties van een website?";
$_LANG['store']['sitelock']['faqFourBodyParagraph1'] = "Een :vulnerabilityStrong is een zwak punt of verkeerde instelling van een website of in de code van een webtoepassing, die door een aanvaller gebruikt kan worden om een zekere mate van controle te krijgen over de site en mogelijk over de hostingserver. De meeste kwetsbaarheden worden op geautomatiseerde wijze misbruikt, met bijvoorbeeld vulnerability scanners en botnets.";
$_LANG['store']['sitelock']['faqFourBodyParagraph2'] = ":malwareStrong, een verzamelnaam voor kwaadaardige software, wordt gebruikt om gevoelige gegevens te verzamelen, ongeoorloofde toegang tot websites te krijgen en zelfs om computers te kapen.";
$_LANG['store']['sitelock']['faqFourTitle'] = "Wat zijn kwetsbaarheden en malware?";
$_LANG['store']['sitelock']['faqOneBody'] = "SiteLock biedt eenvoudige, snelle en betaalbare beveiliging voor alle websites, klein en groot. Het bedrijf is opgericht in 2008 en beschermt wereldwijd meer dan 12 miljoen websites. De cloudgebaseerde productsuite van SiteLock biedt geautomatiseerde detectie van kwetsbaarheden en verwijdert malware, beschermt tegen DDoS-aanvallen, maakt websites sneller en kan een risico-assessment en PCI-compliance check uitvoeren.";
$_LANG['store']['sitelock']['faqOneBodyLearnLinkText'] = "bekijk de video 'How SiteLock Works' door hier te klikken";
$_LANG['store']['sitelock']['faqOneBodyLearnMore'] = "Voor meer informatie over SiteLock, :learnMoreLink";
$_LANG['store']['sitelock']['faqOneTitle'] = "Wat is SiteLock?";
$_LANG['store']['sitelock']['faqSixBody'] = "Het SiteLock Trust Seal is een breed erkende beveiligingsbadge die op websites kan worden weergeven. Het is een zichtbare indicatie dat de website veilig is en vrij van malware. Om het zegel aan een website toe te voegen, is het voldoende om het codefragment van SiteLock op te nemen in de footer van de website.";
$_LANG['store']['sitelock']['faqSixTitle'] = "Wat is het SiteLock Trust Seal?";
$_LANG['store']['sitelock']['faqThreeBody'] = "Een uitgebreide websitescan met de technologie van SiteLock omvat het volgende:";
$_LANG['store']['sitelock']['faqThreeBodyList1'] = "SiteLock controleert de bestanden van de website dagelijks op malware. Als er malware wordt gevonden, wordt de sitehouder onmiddellijk op de hoogte gebracht. Met de uitgebreide scans van SiteLock kan malware ook automatisch worden verwijderd.";
$_LANG['store']['sitelock']['faqThreeBodyList1Title'] = "Scannen en verwijderen van malware die in bestanden zit";
$_LANG['store']['sitelock']['faqThreeBodyList2'] = "SiteLock scant webapplicaties op veelvoorkomende kwetsbaarheden die tot een inbreuk kunnen leiden.";
$_LANG['store']['sitelock']['faqThreeBodyList2Title'] = "Scannen op kwetsbaarheden";
$_LANG['store']['sitelock']['faqThreeBodyList3'] = "SiteLock heeft de technologie om kwetsbaarheden in uw contentbeheersysteem (CMS) automatisch te patchen.";
