$_LANG['store']['socialbee']['content']['header'] = "Handel al uw sociale mediataken af vanuit één plek.";
$_LANG['store']['socialbee']['content']['p1'] = "Wie handmatig sociale media-accounts beheert heeft doorgaans vele uren nodig om te jongleren met verschillende platforms in meerdere tabbladen.";
$_LANG['store']['socialbee']['content']['p2'] = "SocialBee maakt het makkelijker, door berichten vooraf aan te maken en in te plannen, zodat accounts actief blijven, ook wanneer het achter de schermen druk is of het tijd is voor een pauze. Het regelt het posten, bespaart de stress van het handmatig posten, en biedt AI-hulpprogramma's om supersnel content te genereren.";
$_LANG['store']['socialbee']['content']['p3'] = "Het is ook mogelijk om te reageren op opmerkingen, vermeldingen en berichten, samen te werken met een team en prestaties bij te houden, allemaal zonder een tweede tabblad te openen.";
$_LANG['store']['socialbee']['faq']['a1'] = "Het is mogelijk om content te beheren en in te roosteren voor populaire platforms zoals Facebook, Instagram, Threads, X™ (voorheen Twitter™), LinkedIn, Pinterest, Google Business Profile™, TikTok, YouTube™ en Bluesky.";
$_LANG['store']['socialbee']['faq']['a2']['i1'] = "Een alles-in-één hulppprogramma voor het beheer van sociale media die alles afhandelt, van het maken, plannen en delen van content tot analyses, sociale inbox en samenwerking in teams.";
$_LANG['store']['socialbee']['faq']['a2']['i2'] = "Support via <a href='href=https://socialbee.com/calendar/'>telefoongesprekken</a>, chat- of e-mail. We zijn een van de weinige hulpprogramma's voor sociale media waar het nog steeds mogelijk is om telefonische ondersteuning te krijgen.";
$_LANG['store']['socialbee']['faq']['a2']['i3'] = "<a href='https://socialbee.com/webinars/'>Maandelijkse live demo's</a> over het gebruik van SocialBee, <a href='https://help.socialbee.com/'>gedetailleerde documentatie met ondersteuningsinformatie</a>, <a href='https://www.youtube.com/@SocialBeeHQ'>korte tutorials</a>en vele <a href='https://socialbee.com/resources/'>andere bronnen om te helpen met sociale media</a>.";
$_LANG['store']['socialbee']['faq']['a2']['i4'] = "Een <a href='https://socialbee.com/roadmap/'>transparante roadmap van ons product</a>, voor wat er binnenkort gebeurt bij SocialBee.";
$_LANG['store']['socialbee']['faq']['a2']['i5'] = "<a href='https://changelog.socialbee.com/'>Maandelijkse productreleases</a>.";
$_LANG['store']['socialbee']['faq']['a2']['text'] = "SocialBee heeft de volgende voordelen:";
$_LANG['store']['socialbee']['faq']['a3'] = "Gebruikers kunnen hulp krijgen van SocialBee via chat, <a href='mailto:hello@socialbee.com'>email</a>, <a href='https://socialbee.com/calendar/'>calls</a> en een <a href='https://help.socialbee.com/'>goedgevulde kennisbank</a> vol nuttige informatie en verwijzingen.";
$_LANG['store']['socialbee']['faq']['a4']['text'] = "De agency-pakketten (Pro50, Pro100 en Pro150) hebben dezelfde functies als het Pro-abonnement. De belangrijkste verschillen zijn het aantal social media-profielen dat kan worden gekoppeld, het aantal workspaces, en het aantal gebruikers dat aan een workspace kan worden toegevoegd:";
$_LANG['store']['socialbee']['faq']['a5'] = "De servers van SocialBee bevinden zich in Ierland, Europa.";
$_LANG['store']['socialbee']['faq']['q1'] = "Welke sociale mediaplatforms kan ik met SocialBee beheren?";
$_LANG['store']['socialbee']['faq']['q2'] = "Wat maakt SocialBee beter dan andere oplossingen?";
$_LANG['store']['socialbee']['faq']['q3'] = "Welke ondersteuningsopties zijn er beschikbaar voor gebruikers van SocialBee?";
$_LANG['store']['socialbee']['faq']['q4'] = "Verschillen de agency-pakketten van SocialBee van het reguliere Pro-pakket?";
