$_LANG['store']['socialbee']['faq']['unanswered'] = "Meer vragen?";
$_LANG['store']['socialbee']['features']['analyze']['i1'] = "Krijg een helder overzicht van de ontwikkelingen van uw sociale media met eenvoudig te begrijpen statistieken, grafieken, kaarten en meer.";
$_LANG['store']['socialbee']['features']['analyze']['i2'] = "Volg de engagement, impressies, klikfrequentie en de groei van het aantal volgers in de loop van de tijd voor al uw socialemedia-accounts.";
$_LANG['store']['socialbee']['features']['analyze']['i3'] = "Controleer hoe individuele berichten het doen om te ontdekken wat aanslaat.";
$_LANG['store']['socialbee']['features']['analyze']['i4'] = "Vergelijk de prestaties van de verschillende platforms om te bepalen waar uw inspanning het meeste oplevert.";
$_LANG['store']['socialbee']['features']['analyze']['i5'] = "Filter analytics per platform en datumbereik voor een duidelijker beeld.";
$_LANG['store']['socialbee']['features']['analyze']['i6'] = "Download professionele PDF-verslagen met analyses om te delen met klanten en teamleden.";
$_LANG['store']['socialbee']['features']['collaborate']['i1'] = "Geef feedback en tag collega's direct onder content-concepten.";
$_LANG['store']['socialbee']['features']['collaborate']['i2'] = "Vereis goedkeuring van berichten voor ze live gaan om spelfouten en vergissingen er op tijd uit te halen.";
$_LANG['store']['socialbee']['features']['collaborate']['i3'] = "Volg de activiteiten van het team om te weten wie waaraan heeft gewerkt en wanneer.";
$_LANG['store']['socialbee']['features']['collaborate']['i4'] = "Voorkom dubbel werk met een gedeelde ruimte voor samenwerking.";
$_LANG['store']['socialbee']['features']['collaborate']['i5'] = "Geef teamleden specifieke rechten op basis van hun rol.";
$_LANG['store']['socialbee']['features']['collaborate']['i6'] = "Beheer meerdere merken of klanten met aparte, georganiseerde werkruimten.";
$_LANG['store']['socialbee']['features']['create']['i1'] = "SocialBee is geïntegreerd met Canva, Unsplash en GIPHY om eenvoudig beelden voor berichten aan te maken en beheren.";
$_LANG['store']['socialbee']['features']['create']['i2'] = "Genereer binnen een paar seconden onderschriften en afbeeldingen met AI en krijg toegang tot meer dan 1.000 kant-en-klare prompts om tijd te besparen.";
$_LANG['store']['socialbee']['features']['create']['i3'] = "Pas berichten voor elk platform automatisch aan, met AI of handmatig, om ervoor te zorgen dat de content optimaal werkt, waar het ook wordt gedeeld.";
$_LANG['store']['socialbee']['features']['create']['i4'] = "Laat Copilot, de AI-assistent van SocialBee, binnen een paar minuten een gepersonaliseerd contentplan schrijven. Het is niet meer nodig om te gokken wanneer u wat en wanneer u moet posten.";
$_LANG['store']['socialbee']['features']['create']['i5'] = "Organiseer berichten in mappen per onderwerp, zodat het contentplan divers en goed gestructureerd blijft.";
$_LANG['store']['socialbee']['features']['create']['i6'] = "Experimenteer met verschillende soorten berichten zoals afbeeldingen, video's, carrousels, stories en reels, om te ontdekken wat het beste aansluit bij uw publiek.";
$_LANG['store']['socialbee']['features']['engage']['i1'] = "Reageer op alle opmerkingen, mentions en DM's op sociale mediaplatforms vanuit één eenvoudig te beheren inbox.";
$_LANG['store']['socialbee']['features']['engage']['i2'] = "Bespaar tijd en blijf hou gesprekken in de gaten zonder te hoeven schakelen tussen verschillende socialmedia-accounts.";
$_LANG['store']['socialbee']['features']['engage']['i3'] = "Ontvang een melding bij interacties met uw socialemedia-accounts, zodat u nooit belangrijke berichten of kansen voor engagement misloopt.";
$_LANG['store']['socialbee']['features']['engage']['i4'] = "Communiceer in realtime met volgers om uw community te laten groeien en vragen van klanten te snel te beantwoorden.";
$_LANG['store']['socialbee']['features']['engage']['i5'] = "Houd in de gaten wanneer uw brand wordt genoemd om te weten wat mensen zeggen, en houd gesprekken en feedback bij.";
$_LANG['store']['socialbee']['features']['engage']['i6'] = "Gebruik forums en streams om opmerkingen, vermeldingen en berichten te organiseren op een manier die gemakkelijk is te beheren.";
$_LANG['store']['socialbee']['features']['schedule']['i1'] = "Rooster berichten voor grote platforms zoals Facebook®, Instagram, LinkedIn®, TikTok, Pinterest en meer in, vanaf één plek.";
$_LANG['store']['socialbee']['features']['schedule']['i2'] = "Organiseer berichten met een visuele kalender die in één oogopslag uw volledige socialemediastrategie laat zien.";
$_LANG['store']['socialbee']['features']['schedule']['i3'] = "Rooster berichten van tevoren in en zet ze in de wachtrij om social media-accounts actief te houden zonder steeds handmatig te posten.";
$_LANG['store']['socialbee']['features']['schedule']['i4'] = "Rooster content in op specifieke momenten waarop uw publiek actief is en laat SocialBee het beste moment voorstellen op basis van prestaties uit het verleden.";
$_LANG['store']['socialbee']['features']['schedule']['i5'] = "Hergebruik succesvolle niet-tijdgebonden content door berichten opnieuw in te roosteren. Zo houd u uw feed actueel zonder voortdurend nieuwe content aan te moeten maken.";
$_LANG['store']['socialbee']['features']['schedule']['i6'] = "Pauzeer, bewerk of rooster berichten opnieuw in wanneer plannen veranderen. SocialBee biedt de flexibiliteit om de contentkalender waar nodig aan te passen.";
