$_LANG['store']['ssl']['dv']['descriptionContent'] = "<p>Certificaten met domeinvalidatie bieden een voordelige en snelle manier om SSL aan uw website toe te voegen. Domain Validated-certificaten verifiëren dat u de eigenaar bent van het domein, maar valideren uw organisatie verder niet.</p><p>Domain Validated certificaten zijn ideaal voor persoonlijke websites, blogs en sociale media, of sites die geen persoonlijke of vertrouwelijke informatie verwerken. Een Domain Validated certificaat activeert het hangslot van de browser en maakt het gebruik van https mogelijk om bezoekers en klanten van uw website te verzekeren dat u hun privacy serieus neemt.</p>";
$_LANG['store']['ssl']['dv']['descriptionTitle'] = "Wat is Basic DV SSL?";
$_LANG['store']['ssl']['dv']['tagline'] = "Beveilig websites in een paar minuten!";
$_LANG['store']['ssl']['dv']['title'] = "Domein Validatie SSL";
$_LANG['store']['ssl']['ev']['descriptionContent'] = "<p>EV SSL staat voor Extended Validation Certificate, de hoogste SSL-klasse die momenteel beschikbaar is. Hiermee krijgt uw website direct meer geloofwaardigheid en vertrouwen in vergelijking met het gebruik van een door een organisatie of domein gevalideerd SSL-certificaat.</p><p>Extended Validation SSL zal in de meeste gevallen uw bedrijfs- of sitenaam in het groen weergeven. Deze opvallende visuele verificatie geeft bezoekers extra vertrouwen dat er stappen zijn ondernomen om de identiteit van de website en het bedrijf dat ze bezoeken te bevestigen, waardoor het vertrouwen van gebruikers in uw website en de geloofwaardigheid ervan toeneemt. Daarom kiezen de meeste grote bedrijven en organisaties voor EV-certificaten.</p>";
$_LANG['store']['ssl']['ev']['descriptionTitle'] = "Wat is Extended Validation SSL?";
$_LANG['store']['ssl']['ev']['orgInfo'] = "Bevat de gegevens van de EV-geverifieerde organisatie";
$_LANG['store']['ssl']['ev']['orgInfoDescription'] = "De gegevens van het certificaat geven aan dat uw website een Extended Validation SSL-certificaat gebruikt en bevatten de certificaatautoriteit (CA), de geldigheidsstatus en de vervaldatum.";
$_LANG['store']['ssl']['ev']['tagline'] = "Activeer de groene adresbalk voor het hoogste vertrouwen en meer conversies";
