$_LANG['store']['ssl']['landingPage']['evs']['protectSubdomain'] = "Bescherm elk subdomein, inclusief services die essentieel zijn voor de website.<br>Beveilig subdomeinen om essentiële diensten te beschermen, zoals:";
$_LANG['store']['ssl']['landingPage']['evs']['secureTitle'] = "Beveilig de volledige site met wildcard-SSL";
$_LANG['store']['ssl']['landingPage']['evs']['webmailAccess'] = "Webmail (webmail.example.com)";
$_LANG['store']['ssl']['landingPage']['evs']['websiteControl'] = "Configuratiescherm (mail.example.com)";
$_LANG['store']['ssl']['landingPage']['evs']['wildcardDescription'] = "Een wildcard SSL-certificaat beschermt het hoofddomein plus een onbeperkt aantal subdomeinen (bijvoorbeeld mail.example.com of ftp.example.com). Ook wie niet zelf subdomeinen heeft aangemaakt, beschikt waarschijnlijk over meerdere subdomeinen voor functies die horen bij het hostingpakket.";
$_LANG['store']['ssl']['landingPage']['evs']['wildcardSubtitle'] = "Een wildcard SSL-certificaat is de beste manier om een volledige website te beveiligen en gebruikers veilig te houden.";
$_LANG['store']['ssl']['landingPage']['faq']['a1'] = "SSL-certificaten maken het versleutelen van gegevens op internet mogelijk en zorgen voor een veilige overdracht van gegevens van de webserver naar de browser. Met SSL kunnen websites het https-protocol gebruiken, waarbij in de webbrowser van de eindgebruiker een hangslot wordt getoond om aan te geven dat de verbinding is beveiligd.";
$_LANG['store']['ssl']['landingPage']['faq']['a2'] = "SSL-certificaten zijn essentieel voor de goede werking van het internet. Ze versleutelen niet alleen de communicatie tussen uw computer en de server waarop een website zich bevindt, maar ze verifiëren ook dat sites zijn wat ze beweren te zijn.";
$_LANG['store']['ssl']['landingPage']['faq']['a3'] = "Er zijn drie verschillende niveaus van controle waarop SSL-certificaten zijn gebaseerd. Domain Validated (DV), Organization Validated (OV) en Extended Validation (EV). Het belangrijkste verschil tussen deze certificaten zit in de informatie die de certificaatautoriteit, RapidSSL, GeoTrust of DigiCert, nodig heeft en valideert voor ze een certificaat uitgeven. Hogere certificaatniveaus vereisen meer informatie en worden vaak weergegeven in de browserbalk. Zo maakt EV SSL de browserbalk groen en toont het de naam van de organisatie aan bezoekers om ze meer vertrouwen te geven.";
$_LANG['store']['ssl']['landingPage']['faq']['a4'] = "Een Wildcard SSL-certificaat biedt dezelfde functies voor versleuteling en authenticatie als andere SSL-certificaten, maar het kan ook worden toegepast op een onbeperkt aantal subdomeinen die bij een website horen. Een Wildcard SSL-certificaat ondersteunt het hoofddomein (example.com) en de bijbehorende subdomeinen.";
$_LANG['store']['ssl']['landingPage']['faq']['a5'] = "Certificaten met EV of Extended Validation vormen de hoogste klasse SSL die beschikbaar is en geven uw website de meeste geloofwaardigheid en vertrouwen. EV verzekert consumenten ervan dat hun persoonlijke en financiële informatie wordt beschermd op het hoogste niveau van authenticatie. Er worden aanvullende verificaties uitgevoerd, zoals controles van bedrijfsagentschappen, contactgegevens van aanvragers en of het bedrijf minimaal 3 jaar bestaat. EV-certificaten zijn vooral geschikt voor bedrijfskritische webpagina's.";
$_LANG['store']['ssl']['landingPage']['faq']['a6'] = "Het is altijd mogelijk om naar ons overstappen, op elk moment. We bieden hele scherpe prijzen en voor wie al over een bestaand certificaat beschikt voegen we de resterende geldigheid van het bestaande SSL-certificaat aan het nieuwe certificaat toe, tot een maximum van 12 extra maanden.";
