$_LANG['store']['ssl']['landingPage']['help']['dv']['type'] = "Zie het aanvragen van DV als het aanvragen van een bonuskaart in de supermarkt: er is geen identificatiebewijs nodig om er eentje aan te vragen, de eisen zijn minimaal en er zijn geen wachttijden.";
$_LANG['store']['ssl']['landingPage']['help']['dv']['verify'] = "Controleert alleen wie de domeinhouder is en wie het domein in beheer heeft";
$_LANG['store']['ssl']['landingPage']['help']['ev']['browse'] = "Extended Validation-certificaten bekijken";
$_LANG['store']['ssl']['landingPage']['help']['ev']['compliance'] = "Zorgt voor compatibiteit met de browser en andere systemen";
$_LANG['store']['ssl']['landingPage']['help']['ev']['for'] = "Ideaal voor gevoelige webpagina's zoals e-commerce, online bankieren en registraties";
$_LANG['store']['ssl']['landingPage']['help']['ev']['issued'] = "Doorgaans binnen 1-3 dagen uitgegeven";
$_LANG['store']['ssl']['landingPage']['help']['ev']['title'] = "Uitgebreide validatie (EV)";
$_LANG['store']['ssl']['landingPage']['help']['ev']['type'] = "Zie het aanvragen van EV als het aanvragen van een nieuw identiteitsbewijs wanneer u de oude bent verloren: de eisen zijn veel strenger, de wachttijden zijn veel langer en er is een uitgebreidere verificatie van wie u daadwerkelijk bent dan bij een klantenkaart of zelfs een bankpas. Internationaal wordt EV erkend als de meest vertrouwde manier om uw identiteit te verifiëren.";
$_LANG['store']['ssl']['landingPage']['help']['ev']['verify'] = "Op standaarden gebaseerde authenticatie, het hoogste niveau van authenticatie voor SSL-certificaten";
$_LANG['store']['ssl']['landingPage']['help']['guide'] = "Hoewel alle sites behoefte hebben aan beveiliging, zitten niet alle SSL-certificaten op dezelfde manier in elkaar. Het onderstaande overzicht is bedoeld om makkelijker te kunnen beslissen welk type certificaat geschikt is voor welk doel.";
$_LANG['store']['ssl']['landingPage']['help']['ov']['browse'] = "Organization Validation-certificaten bekijken";
