$_LANG['store']['ssl']['landingPage']['padlock'] = "Plaatst een hangslot-icoon naast het webadres in de browser.";
$_LANG['store']['ssl']['landingPage']['rapidSSL']['recommended'] = "Persoonlijke websites zonder subdomeinen. (Let op, de meeste sites beschikken over subdomeinen.)";
