$_LANG['store']['ssl']['landingPage']['recommendedFor'] = "Aanbevolen voor";
$_LANG['store']['ssl']['landingPage']['secureConnection'] = "Zorgt voor een beveiligde verbinding tussen browser en server.";
$_LANG['store']['ssl']['landingPage']['secureInMinutes'] = "Beveilig sites in een paar minuten met onze volledig geautomatiseerde uitgifte en implementatie";
$_LANG['store']['ssl']['landingPage']['tagline1'] = "Beveilig uw site en geef bezoekers meer vertrouwen.";
$_LANG['store']['ssl']['landingPage']['tagline2'] = "Met een breed scala aan merken bieden wij het juiste certificaat voor alle behoeften op het gebied van sitebeveiliging";
$_LANG['store']['ssl']['landingPage']['title'] = "SSL-certificaten";
$_LANG['store']['ssl']['landingPage']['viewAll'] = "Alle SSL-certificaten bekijken";
$_LANG['store']['ssl']['landingPage']['what'] = "Wat is SSL?";
$_LANG['store']['ssl']['landingPage']['whatInfo'] = "SSL-certificaten zijn een belangrijk fundament van de beveiliging op internet. Ze zijn nodig om versleutelde verbindingen tot stand te brengen en zorgen ervoor dat gegevens veilig worden verzonden tussen de browser op de computer van de gebruiker en een website of een server.";
$_LANG['store']['ssl']['ov']['descriptionContent'] = "<p>Organization Validated SSL-certificaten bieden direct bevestiging van uw bedrijfsidentiteit en sterke SSL-bescherming voor uw website.</p><p>OV SSL is een door de organisatie gevalideerd certificaat dat uw website extra geloofwaardigheid geeft ten opzichte van domeingevalideerde SSL-certificaten. Het activeert het browserhangslot en https, toont uw huisstijl en verzekert uw klanten dat u beveiliging serieus neemt. Bezoekers van de site kunnen controleren dat de website wordt beheerd door een legitiem bedrijf en geen oplichtingssite is.</p>";
$_LANG['store']['ssl']['ov']['descriptionTitle'] = "Wat is Organization Validation SSL?";
