$_LANG['store']['ssl']['wildcard']['descriptionContent'] = "<p>Met wildcard SSL kunt u een onbeperkt aantal subdomeinen beveiligen met één certificaat. Het is een fantastische oplossing voor iedereen die meerdere sites of pagina's op een en hetzelfde domein host of beheert. De eenmalige kosten van het certificaat dekken alle extra subdomeinen die u in de toekomst toevoegt.</p><p>In tegenstelling tot een standaard SSL-certificaat dat wordt uitgegeven voor een volledig gekwalificeerde domeinnaam (zoals www.example.com) en dat alleen kan worden gebruikt om dat exacte domein te beveiligen, wordt een Wildcard SSL-certificaat uitgegeven voor *.example.com, waarbij het sterretje alle mogelijke subdomeinen vertegenwoordigt.</p><p>Wildcard SSL is beschikbaar voor DV- en OV SSL-certificaten.</p>";
$_LANG['store']['ssl']['wildcard']['descriptionTitle'] = "Wat is een Wildcard SSL-certificaat?";
